export async function fixture(page,delayMs=0){await page.addInitScript(delay=>{
 window.Pose=class {setOptions(){} onResults(cb){this.cb=cb}async close(){} async send({image}){if(delay)await new Promise(r=>setTimeout(r,delay));const time=image.currentTime||0,phase=time%3,angle=phase<1||phase>=2?168:95,rad=angle*Math.PI/180;const points=Array.from({length:33},()=>({x:.5,y:.5,visibility:.99}));points[23]={x:.5,y:.35,visibility:.99};points[25]={x:.5,y:.6,visibility:.99};points[27]={x:.5+Math.sin(rad)*.25,y:.6-Math.cos(rad)*.25,visibility:.99};this.cb({poseLandmarks:points})}};
 Object.defineProperty(navigator.mediaDevices,'getUserMedia',{value:async()=>{const canvas=document.createElement('canvas');canvas.width=160;canvas.height=160;const ctx=canvas.getContext('2d');const timer=setInterval(()=>{ctx.fillStyle='gray';ctx.fillRect(0,0,160,160)},30);const stream=canvas.captureStream(30);for(const track of stream.getTracks()){const stop=track.stop.bind(track);track.stop=()=>{clearInterval(timer);window.fixtureStopped=true;stop()}}return stream}})
},delayMs);await page.goto('/#home');await page.locator('#onboardingSkip').click();}
